SELECT r.x AS x, t.v1 AS v1, t.v2 AS v2 FROM (SELECT * FROM (SELECT InvoiceLineId AS x, InvoiceLineId AS v1 FROM InvoiceLine) AS r WHERE r.v1 IN (SELECT t.x FROM (SELECT r.x AS x, t.v1 AS v1 FROM (SELECT InvoiceLineId AS x, InvoiceId AS v1 FROM InvoiceLine) AS r JOIN (SELECT * FROM (SELECT r.x AS x, t.v1 AS v1 FROM (SELECT InvoiceId AS x, CustomerId AS v1 FROM Invoice) AS r JOIN (SELECT CustomerId AS x, Country AS v1 FROM Customer) AS t ON r.v1 = t.x) AS r WHERE r.v1 = 'Brazil') AS t ON r.v1 = t.x) AS t)) AS r JOIN (SELECT r.x AS x, r.v1 AS v1, t.v1 AS v2 FROM (SELECT r.x AS x, t.v1 AS v1 FROM (SELECT InvoiceLineId AS x, TrackId AS v1 FROM InvoiceLine) AS r JOIN (SELECT TrackId AS x, Name AS v1 FROM Track) AS t ON r.v1 = t.x) AS r JOIN (SELECT r.x AS x, t.v1 AS v1 FROM (SELECT r.x AS x, t.v1 AS v1 FROM (SELECT r.x AS x, t.v1 AS v1 FROM (SELECT InvoiceLineId AS x, TrackId AS v1 FROM InvoiceLine) AS r JOIN (SELECT TrackId AS x, AlbumId AS v1 FROM Track) AS t ON r.v1 = t.x) AS r JOIN (SELECT AlbumId AS x, ArtistId AS v1 FROM Album) AS t ON r.v1 = t.x) AS r JOIN (SELECT ArtistId AS x, Name AS v1 FROM Artist) AS t ON r.v1 = t.x) AS t ON r.x = t.x) AS t ON r.v1 = t.x;
